head.script:
///////// 1. 변수 및 선언 영역 /////////
// 원본 : /lstproc/ULDSTF05702.gfm (행사가격 정정 — 신주인수권증권)
/*
 * 화면 동작
 *  - [종목 찾기](ULDSTF92017)로 신주인수권증권 종목을 고르면 행사가격 조정내역 목록과 변경전 행사가격을 조회하고 신규 입력 상태가 된다.
 *  - 변경상장일·변경사유·변경후 행사가격을 입력해 [저장]하면 검증 → 확인 → 업무처리번호 채번 → 등록한다.
 *  - 목록 행을 누르면 그 건을 상세로 읽고, 변경상장일이 오늘 이후면 [수정]·[삭제], 지났으면 모두 잠근다.
 *  - 저장·수정·삭제에 성공하면 신규 입력 상태로 되돌리고 목록·변경전 행사가격을 다시 조회한다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05702/ULDSTF05702.md (§번호는 이 문서의 절)
 */

// 화면 상태값
scwin.secugrpId = "";       // 증권그룹ID — 원본 fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()) (메뉴 STF05702 → SW)
scwin.isurCd = "";          // 발행회사코드 — 종목 찾기 결과 (원본 vIsurCd, 삭제 요청에 쓴다)
scwin.bzProcsNo = "";       // 업무처리번호 — 목록에서 고른 건, 비면 신규 (원본 vBzProcsNo)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제 (원본 trsIdx)

// 고정값
scwin.COMPLETE_YN_OK = "Y"; // 등록·수정·삭제 응답 completeYn 의 성공 값 — TODO: 명세에 값이 없어 가정 (§10 #5)

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
// [신규]는 원본 buttonSet 밖의 버튼이라 늘 활성이다(§4).
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete"     // [삭제]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — 버튼 신규 상태 → 증권그룹ID → 달력·조회 Enter 키 바인딩. 초기 조회는 없다(종목을 골라야 조회). (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 버튼 — 신규 상태(저장만 활성). 원본 buttonSet.setSaveInfo/setUpdateInfo/setDeleteInfo + setInsertStatus
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);

    // 2) 증권그룹ID — 이 화면 메뉴(STF05702)는 업무공통 표에서 SW(신주인수권증권) 하나다(§3, §10 #8)
    scwin.secugrpId = $c.lc.glb.SECUGRP_ID_SW;

    // 3) 달력 검사 바인딩(1회, 규칙 37) · 조회 영역 Enter 키(규칙 22)
    $c.date.checkCalendarFormat(edt_CHG_DD, "yyyyMMdd");
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 조회 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_ISU_NM_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_ISU_NM_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.img_ISU_NM_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncellclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 행사가격 조정내역 행 클릭 — 그 건을 상세로 읽는다. (원본 grd_List OnClick → fn_read_sync)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.selectDetail(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.grd_List_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.btn_New_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 버튼 클릭 — 원본도 조회 버튼과 같은 처리(입력 초기화 + 재조회)다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_New_onclick = async function (e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.btn_New_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.btn_Delete_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectBfprc
 * @author Inswave
 * @date 2026. 10. 28
 * @description 변경전 행사가격 조회 — 응답 body.bfchgExerPrc 를 dma_detail 에 넣는다. (원본 fn_bfprc — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectBfprc = async function () {
    const sbmOptions = {
        id : "sbm_selectBfprc",
        method : "get",
        action : "/api/listing/lstproc/warrant/exerprcchange/select-bfprc",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : dma_search.get("isuCd") });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return;

    dma_detail.set("bfchgExerPrc", result.responseJSON.body?.bfchgExerPrc ?? "");
};

/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 행사가격 조정내역 목록 조회 — 건수를 표시한다. (원본 fn_list_sync + dts_List OnLoadCompleted — §5.2)
 * @returns
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/warrant/exerprcchange/select-list",
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : dma_search.get("isuCd") });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return;

    panel_page.setValue(dlt_list.getRowCount());    // 원본 FillGridHeaderTotalCnt(rowcount, panel_page)
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상세 조회 — 고른 행의 업무처리번호로 읽고, 변경상장일이 오늘 이후면 수정 상태, 지났으면 모두 잠근다.
 * (원본 fn_read_sync + dts_Mst OnLoadCompleted — §5.3, §6.4)
 * @param {Number} rowIndex 목록 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.selectDetail = async function (rowIndex) {
    const bzProcsNo = String(dlt_list.getCellData(rowIndex, "bzProcsNo") ?? "");
    if ($c.util.isEmpty(bzProcsNo)) return;

    const sbmOptions = {
        id : "sbm_selectDetail",
        method : "get",
        action : "/api/listing/lstproc/warrant/exerprcchange/select-one",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    // 행을 빠르게 바꿔 누르면 마지막 요청이 이긴다(가이드 §5 — 취소된 앞 요청의 reject 는 handleError 가 무시)
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo }, null, { onDuplicate : "abort" });
    if (result?.skipped) return;
    if (!result.responseJSON?.success) return;

    // 응답을 받은 뒤에만 업무처리번호를 바꾼다 — 실패하면 이전 상태 그대로(§8 #6)
    scwin.bzProcsNo = bzProcsNo;
    // 변경상장일 ≤ 오늘 → error(모두 잠김), 그 밖 → update (원본 cGetToday < CHG_DD)
    $c.stf.setButtonSetWithDate(edt_CHG_DD, false, "grpBtnBox", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 등록(I)·수정(U). dma_detail 을 ref 로 보내고, 성공하면 신규 상태로 되돌려 다시 조회한다.
 * (원본 fn_trs + trs_Save OnSuccess/OnFail — §5.4, §5.5)
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob) {
    const jobNm = (trJob === "I") ? "저장" : "수정";

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/warrant/exerprcchange/register"
                                 : "/api/listing/lstproc/warrant/exerprcchange/modify",
        ref : "dma_detail",
        target : "dma_result=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 전문 준비 — 원본 fn_trs 의 dts_Mst 값 채우기(업무처리번호·종목코드). 변경전·변경후 행사가격은 바인딩 값 그대로.
    // TODO: 원본이 보내던 ISUR_CD·LIST_BZ_TP_CD(150)·TRS_IDX·DIV_IDX[0](11)·COUNT 는 명세 요청에 없어 보내지 않는다 (§10 #3)
    dma_detail.set("bzProcsNo", scwin.bzProcsNo);
    dma_detail.set("isuCd", dma_search.get("isuCd"));

    dma_result.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!await scwin.checkResult(result, jobNm)) return;

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));
    await scwin.reload();
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제. 명세대로 업무처리번호·발행회사코드를 requestData 로 보내고, 성공하면 신규 상태로 되돌려 다시 조회한다.
 * (원본 fn_trs(TRS_IDX_DELETE) + trs_Save OnSuccess — §5.6)
 * @returns
 * @hidden N
 */
scwin.removeTrs = async function () {
    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/warrant/exerprcchange/remove",
        target : "dma_result=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    dma_result.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo, isurCd : scwin.isurCd });
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!await scwin.checkResult(result, "삭제")) return;

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    await scwin.reload();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 28
 * @description 조회·신규 — 종목이 없으면 안내, 있으면 신규 상태로 되돌려 목록·변경전 행사가격을 다시 조회한다.
 * (원본 btn_Search·btn_New onclick — §6.1)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    if ($c.util.isEmpty(dma_search.get("isuCd"))) {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return;
    }
    await scwin.reload();
};

/**
 * @method
 * @name scwin.reload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 상태로 되돌린 뒤 목록 → 변경전 행사가격 순서로 조회한다.
 * (원본 fn_initItem + fn_list_sync + fn_bfprc — 종목 선택·저장 성공 뒤, 조회·신규 버튼 — §6.2)
 * @returns
 * @hidden N
 */
scwin.reload = async function () {
    scwin.initItem();
    await scwin.selectList();
    await scwin.selectBfprc();
};

/**
 * @method
 * @name scwin.initItem
 * @author Inswave
 * @date 2026. 10. 28
 * @description 입력 초기화 — 버튼 신규 상태, 상세 비우기, 업무처리번호 비우기. (원본 fn_initItem — §6.3)
 * @returns
 * @hidden N
 */
scwin.initItem = function () {
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    dma_detail.setEmptyValue();
    scwin.bzProcsNo = "";
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목 찾기. 신주인수권증권 종목(ULDSTF92017)을 골라 조회 영역에 채우고 다시 조회한다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 img_ISU_NM onclick + fn_GetParIsuCd + fn_SetParIsuCd + fn_PopFindIsu — §6.5)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // AS-IS arr[0]·arr[1] "" (검색어 없음), arr[2] 증권그룹ID → pcc 는 secugrpId 만 넘긴다
    const result = await $c.lc.popFindIsu(scwin.secugrpId);
    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 종목코드로 판정(원본 DBCLICKYN "Y" 일 때만 반영)
    if (result?.isCloseButtonClick === true || $c.util.isEmpty(result?.isuCd)) return;

    dma_search.set("isuCd", result.isuCd);
    dma_search.set("isuNm", result.isuKorNm ?? "");
    scwin.isurCd = result.isurCd ?? "";

    await scwin.reload();
};

/**
 * @method
 * @name scwin.getListBzTpCd
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장업무구분코드 — 신주인수권증권(SW)이면 150(신주인수권증권 행사가격), 그 밖은 빈 값. (원본 fn_getListBzTpCd — §6.6)
 * @returns {String} 상장업무구분코드
 * @hidden N
 */
scwin.getListBzTpCd = function () {
    return (scwin.secugrpId === $c.lc.glb.SECUGRP_ID_SW) ? $c.lc.glb.LIST_BZ_TP_CD_150 : "";
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서를 따른다 — 필수·길이는 공통 검증(validateDataCollect)을
 * 원본 순서대로 나눠 부르고, 그 사이에 현재일 비교를, 끝에 업무 중복 입력 확인(서버)을 둔다. (§6.7)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    const curDate = $c.date.getServerDateTime().substring(0, 8);
    const isuCd = dma_search.get("isuCd");

    // 1) 종목
    if ($c.util.isEmpty(isuCd)) {
        await $c.win.alert("[종목코드]를 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }

    // 2) 변경상장일 필수
    const ddOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            edt_CHG_DD : { required : true, format : "date", name : "변경상장일" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_Item, ddOptions)) return false;

    // 3) 변경상장일은 현재일 이후 (원본 cGetToday >= CHG_DD 면 실패)
    const chgDd = dma_detail.get("chgDd");
    if (chgDd <= curDate) {
        await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }

    // 4) 변경사유 필수·1000byte 이하(원본 checkMaxLength — 한글 2byte), 변경후 행사가격 필수
    const etcOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txb_CHG_RSN_CONTN : { required : true, maxLengthB : 1000, name : "변경사유" },
            edt_AFCHG_EXER_PRC : { required : true, name : "변경후 행사가격(원)" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_Item, etcOptions)) return false;

    // 5) 업무 중복 입력 확인 — 종목·변경상장일·업무처리번호(신규는 빈 값)·상장업무구분 150
    // TODO: pcc checkBzDoubleInput 은 주식 변경상장 경로(stock/chglisting/check-double-input)이고 명세에 없다 — 150 업무에서도 맞는지 확인 (§5.7, §10 #4)
    // TODO: pcc 결함 (§10 #4, 배포 전 차단) — 응답에 disclsProcsDdtm 이 없으면(undefined) 중복으로 보고 false 라 저장·수정이 늘 막힌다.
    //       skipped 가드도 없다 — pcc 수정 요청
    return await $c.lc.checkBzDoubleInput(isuCd, chgDd, dma_detail.get("bzProcsNo"), scwin.getListBzTpCd());
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 28
 * @description 업무처리번호를 새로 받는다. $c.stf.getNewBzProcNo 는 응답 봉투를 그대로 돌려줄 수 있어 body 를 꺼내고,
 * body 가 문자열이면 그대로, 객체면 bzProcsNo 를 문자열로 만든다. 14자리 검사는 호출부(scwin.save)가 한다. (§5.8)
 * @returns {Promise<String>} 업무처리번호 (실패면 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // TODO: 채번 주체 — 명세 register 설명("업무처리번호 채번 + 상장업무처리로그 반영")이 서버 채번일 수도 있다. 지금은 원본대로 화면 채번 (§10 #2)
    // TODO: 채번 응답 모양 미확정 — body 가 문자열인지 { bzProcsNo } 인지 확인 (§10 #2). 지금은 둘 다 받는다.
    const res = await $c.stf.getNewBzProcNo();
    const body = res?.body ?? res;
    return String((typeof body === "object" && body !== null) ? (body.bzProcsNo ?? "") : (body ?? ""));
};

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 10. 28
 * @description 등록·수정·삭제 응답 판정. 통신 실패이거나 completeYn 이 와서 성공 값이 아니면 MSG-A002 를 안내하고 false.
 * register·remove 는 명세에 응답 정의가 없어 completeYn 이 비어 오면 success 만으로 판정한다. (§5.4~5.6)
 * @param {Object} result executeDynamic 결과
 * @param {String} jobNm 처리명 (저장·수정·삭제)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.checkResult = async function (result, jobNm) {
    // TODO: completeYn 의 성공 값("Y")·register/remove 응답 구조는 가정 — 명세 확인 필요 (§10 #5)
    const completeYn = String(dma_result.get("completeYn") ?? "");
    if (result.responseJSON?.success && (completeYn === "" || completeYn === scwin.COMPLETE_YN_OK)) return true;

    await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
    return false;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 저장. 검증 → 확인 → 채번 → 등록 순서 (원본 fn_save — §6.8, §1.4 업무 4)
 * 채번이 확인보다 뒤라서 취소한 건에는 번호가 소비되지 않는다.
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    // 원본은 채번 직후 vBzProcsNo 에 넣어 실패해도 남았다 — 성공하면 reload 가 비우므로 결과는 같다(§8 #7)
    scwin.bzProcsNo = bzProcsNo;
    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정. 검증 → 확인 → 수정 순서 (원본 fn_update — §6.9, §1.4 업무 5). 원본은 변경 여부를 확인하지 않는다.
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제. 확인을 받은 뒤 삭제한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.10, §1.4 업무 6)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.removeTrs();
};
